/// <summary>
/// The service class for sales order cancel process.
/// </summary>
class METPickListService extends SysOperationServiceBase
{
    #OCCRetryCount

}

Method.Source:
/// <summary>
/// Instantiate new METPickListService object
/// </summary>
/// <returns>New object</returns>
public static METPickListService contruct()
{
    return new METPickListService();
}

    /// <summary>
    /// cancels the sales order.
    /// </summary>
    /// <param name="_contract">
    /// The contract instance
    /// </param>
    /// <returns>
    /// The response <c>METPickListCancelResponseContract</c>
    /// </returns>
    public METPickListCancelResponseContract cancelPickList(METPickListCancelRequestContract pickListCancelRequest)
    {
        METProcessingStatus cancelResult;
        Description255      cancelMessage;

        [cancelResult, cancelMessage] = this.processCancelPickList(pickListCancelRequest);
        
        return METPickListCancelResponseContract::newFromParameters(cancelResult, cancelMessage);
    }

    /// <summary>
    /// cancels the pick list
    /// </summary>
    /// <param name="_pickListCancelRequest">The contract instance</param>
    /// <returns>Container of results</returns>
    public container processCancelPickList(METPickListCancelRequestContract _pickListCancelRequest)
    {
        METProcessingStatus cancelResult;
        Description255      cancelMessage;

        DataAreaId          dataAreaId;
        WMSPickingRouteID   pickingRouteId;
        WMSPickingRoute     pickingRoute;

        dataAreaId  = _pickListCancelRequest.parmDataAreaId();
        pickingRouteId = _pickListCancelRequest.parmPickingRouteId();

        try
        {
            ttsbegin;

            changecompany(dataAreaId)
            {
                pickingRoute = WMSPickingRoute::find(pickingRouteId, true);
        
                if(!pickingRoute.RecId)
                {
                    cancelResult = METProcessingStatus::Error;
                    cancelMessage = "@MET:PickListNotFound";
                }
                else if(!pickingRoute.canBeCancelled())
                {
                    cancelResult = METProcessingStatus::Error;
                    cancelMessage = "@MET:PickListNotActive";
                }
                else
                {
                    pickingRoute.cancel();
                    
                    cancelResult = METProcessingStatus::Success;
                    cancelMessage = "@MET:PickListCancellationSuccessful";
                }

                if(cancelResult == METProcessingStatus::Error)
                {
                    throw error(cancelMessage);
                }

                ttscommit;
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:SalesCancelDeadlock");
                    throw Exception::Deadlock;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:SalesCancelDeadlock");
                throw Exception::Deadlock;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:SalesCancelUpdateConflict");
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:SalesCancelUpdateConflict");
                throw Exception::UpdateConflict;
            }
        }

        return [cancelResult, cancelMessage];
    }
